using System;using System.Collections.Generic;using System.Diagnostics;using System.Linq;using System.Runtime.InteropServices;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using TrayLeaf;
class GlassDragTests {
 static Stopwatch clock=Stopwatch.StartNew();static Dictionary<int,double> colors=new Dictionary<int,double>();static int passed,failed;static void Check(bool ok,string n){Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(ok)passed++;else failed++;}
 static void Pump(int ms){var f=new DispatcherFrame();var t=new DispatcherTimer(DispatcherPriority.Send){Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=delegate{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static int Sample(Window w){var surface=(Border)w.Content;var brush=surface.Background as DrawingBrush;if(brush==null)return -1;var image=((ImageDrawing)((DrawingGroup)brush.Drawing).Children[0]).ImageSource as System.Windows.Media.Imaging.BitmapSource;if(image==null)return -1;var pixel=new byte[4];image.CopyPixels(new Int32Rect(image.PixelWidth/2,image.PixelHeight/2,1,1),pixel,4,0);return pixel[0]|pixel[1]<<8|pixel[2]<<16;}
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);
 static int enters,exits;
 static IntPtr Hook(IntPtr h,int m,IntPtr a,IntPtr b,ref bool handled){if(m==0x231)enters++;if(m==0x232)exits++;return IntPtr.Zero;}
 static double[] Observe(Window w,bool move){int start=DesktopGlass.Frames(w),last=start;var gaps=new List<double>();var lags=new List<double>();int priorColor=-1;var sw=Stopwatch.StartNew();double prev=0;int moves=0;var t=new DispatcherTimer(DispatcherPriority.Send){Interval=TimeSpan.FromMilliseconds(8)};t.Tick+=delegate{if(move){moves++;w.Left=180+35*Math.Sin(moves*.12);w.Top=150+20*Math.Cos(moves*.12);}int sample=Sample(w);double when;if(sample!=priorColor&&colors.TryGetValue(sample,out when)){lags.Add(clock.Elapsed.TotalMilliseconds-when);priorColor=sample;}int n=DesktopGlass.Frames(w);if(n!=last){gaps.Add(sw.Elapsed.TotalMilliseconds-prev);prev=sw.Elapsed.TotalMilliseconds;last=n;}};t.Start();Pump(3200);t.Stop();double sec=sw.Elapsed.TotalSeconds;gaps.Add(sw.Elapsed.TotalMilliseconds-prev);Console.WriteLine("METRIC "+(move?"drag":"idle")+"_moves="+moves);return new[]{(DesktopGlass.Frames(w)-start)/sec,gaps.Max(),lags.Count==0?999:lags.Average()};}
 static void Metric(string n,double v){Console.WriteLine("METRIC "+n+"="+v.ToString("F2",System.Globalization.CultureInfo.InvariantCulture));}
 [STAThread]static int Main(){try{new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var pattern=new Window{Title="TrayLeaf fix3 backdrop fixture",Width=1200,Height=800,Left=90,Top=65,Topmost=true,ShowInTaskbar=false,Background=Brushes.CornflowerBlue};pattern.Show();var surface=new Border{Name="WindowSurface"};var w=new Window{Title="TrayLeaf fix3 drag fixture",Width=800,Height=500,Left=180,Top=150,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brushes.Transparent,Topmost=true,ShowInTaskbar=false,Content=surface};NameScope.SetNameScope(w,new NameScope());w.RegisterName("WindowSurface",surface);w.Resources["Canvas"]=new SolidColorBrush(Color.FromRgb(30,38,52));w.Resources["Text"]=Brushes.White;w.Show();w.Activate();DesktopGlass.Set(w,true);int frame=0;var animate=new DispatcherTimer(DispatcherPriority.Render){Interval=TimeSpan.FromMilliseconds(25)};animate.Tick+=delegate{frame++;var color=Color.FromRgb((byte)(frame*19%255),(byte)(frame*37%255),(byte)(frame*53%255));colors[color.B|color.G<<8|color.R<<16]=clock.Elapsed.TotalMilliseconds;pattern.Background=new SolidColorBrush(color);};animate.Start();Pump(800);var idle=Observe(w,false);var drag=Observe(w,true);Metric("idle_fps",idle[0]);Metric("drag_fps",drag[0]);Metric("idle_max_gap_ms",idle[1]);Metric("drag_max_gap_ms",drag[1]);Metric("drag_idle_ratio",drag[0]/idle[0]);Metric("idle_texture_age_ms",idle[2]);Metric("drag_texture_age_ms",drag[2]);Check(drag[2]<=idle[2]+35,"continuous-drag-latency-not-regressed");Check(idle[0]>=10,"idle-capture-baseline-available");Check(drag[0]>=idle[0]*.75,"continuous-drag-retains-refresh-rate");Check(drag[1]<=Math.Max(200,idle[1]*2),"continuous-drag-no-starved-frame-gaps");// Enter the real Win32 keyboard move modal loop on this fixture only; no global mouse/keyboard injection.
 var hwnd=new WindowInteropHelper(w).Handle;var source=HwndSource.FromHwnd(hwnd);source.AddHook(Hook);int before=DesktopGlass.Frames(w);var nativeClock=Stopwatch.StartNew();var feed=new Thread(delegate(){Thread.Sleep(180);for(int i=0;i<75;i++){PostMessage(hwnd,0x100,new IntPtr(i%20<10?0x27:0x25),new IntPtr(1));Thread.Sleep(40);}PostMessage(hwnd,0x100,new IntPtr(0x0D),new IntPtr(1));Thread.Sleep(300);PostMessage(hwnd,0x100,new IntPtr(0x1B),new IntPtr(1));});feed.IsBackground=true;feed.Start();PostMessage(hwnd,0x112,new IntPtr(0xF010),IntPtr.Zero);Pump(3500);feed.Join(1000);double nativeFps=(DesktopGlass.Frames(w)-before)/nativeClock.Elapsed.TotalSeconds;Metric("native_move_fps",nativeFps);Metric("native_move_enters",enters);Metric("native_move_exits",exits);Check(enters>0&&exits>0,"native-move-modal-loop-exercised");Check(nativeFps>=idle[0]*.70,"native-move-retains-refresh-rate");source.RemoveHook(Hook);
 animate.Stop();pattern.Background=Brushes.Goldenrod;Pump(500);Check(surface.Background is DrawingBrush,"drag-final-background-present");DesktopGlass.Set(w,false);w.Close();pattern.Close();Console.WriteLine("RESULT passed="+passed+" failed="+failed);return failed==0?0:1;}catch(Exception e){Console.Error.WriteLine(e);return 2;}}
}
